contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function: caller supplies a candidate newOwner
    function run(address newOwner) public payable {
        require(true);

        // read owner before
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;

        // Call setOwner as admin (this contract is the deployer/admin of c in the checker setup).
        bool didRevert = false;
        bool ret = false;
        bool success = c.setOwner(newOwner); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            didRevert = true;
        } else {
            didRevert = false;
            ret = success;
        }

        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;

        // General rule: if the call did not revert then it must return true and owner must be updated to newOwner;
        // if it reverted then owner must remain the same as before.
        assert((!didRevert && ret == true && ownerAfter == newOwner) || (didRevert && ownerAfter == ownerBefore));
    }

    receive() external payable { }
}

